"""LEVI automation minion catalog — 471 minions.

Three bloodlines, one pack:
- ``chauncey-intake``: 51 complete rows from Chauncey's own pasted
  automation matrix (Productivity), preserved verbatim as authored,
  plus 1 truncated intake row flagged ``incomplete=True``.
- ``levi-original``: 104 new LEVI-original minions across 10 new
  categories — the double.
- ``levi-original``: 312 more LEVI-original minions across the 11
  categories — the triple.

Every row carries ``signature_id``: the Echo × Mandella
interpenetration signature over the catalog content
(``levi.interpenetration.verify_signatures()`` recomputes it).

Wave-B signature layer (2026-09-18): the 120 agents in System & Device
Care, Security & Privacy, and Smart Home & IoT carry Chauncey's full
signature — every rite runs through Echo, Mandella, REIM, and RIEM,
interpenetrating Wave-A grafts and LEVI-native DNA. Each agent's notes
hold its ``Signature:`` lineage and its ``Uniqueness kept:`` statement.
Ids, names, triggers, conditions, gates, and adapters are unchanged.

Schema fidelity notes (do not "fix"):
- Every row carries ``bridge='Webhook'`` and
  ``usb_auto_launch='n8n'`` exactly as the intake authored them;
  the pairing is his quirk, preserved, not corrected.
- His intake contains near-verbatim duplicate rows (e.g. Note Search
  x3, Weekly Digest x2). Nothing is deleted: each keeps its own id
  and origin. Spot the differences in their notes/workflows.
- Tool columns (MacroDroid, AutoHotkey, AppleScript, Bardeen, ...)
  are plain data references for cross-platform mapping — never
  identity, never branding. LEVI wears no mask.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, List, Optional


@dataclass(frozen=True)
class Minion:
    """One automation minion definition."""

    id: str
    category: str
    subcategory: str
    trigger: str
    condition: str
    android_tool: str
    windows_tool: str
    mac_tool: str
    chrome_extension: str
    bridge: str
    usb_auto_launch: str
    hitl_type: str
    example_rite: str
    notes: str
    origin: str
    incomplete: bool = False
    signature_id: str = ""

    def to_dict(self) -> Dict[str, object]:
        return {
            "id": self.id,
            "category": self.category,
            "subcategory": self.subcategory,
            "trigger": self.trigger,
            "condition": self.condition,
            "android_tool": self.android_tool,
            "windows_tool": self.windows_tool,
            "mac_tool": self.mac_tool,
            "chrome_extension": self.chrome_extension,
            "bridge": self.bridge,
            "usb_auto_launch": self.usb_auto_launch,
            "hitl_type": self.hitl_type,
            "example_rite": self.example_rite,
            "notes": self.notes,
            "origin": self.origin,
            "incomplete": self.incomplete,
            "signature_id": self.signature_id,
        }


