def _build() -> List[Minion]:
    return [Minion(**r) for r in _RAW]


MINIONS: List[Minion] = _build()


def categories() -> List[str]:
    """Category names in first-seen order."""
    seen: List[str] = []
    for b in MINIONS:
        if b.category not in seen:
            seen.append(b.category)
    return seen


def by_category(category: str) -> List[Minion]:
    want = category.strip().lower()
    return [b for b in MINIONS if b.category.strip().lower() == want]


def by_hitl(hitl_type: str) -> List[Minion]:
    want = hitl_type.strip().lower()
    return [b for b in MINIONS if b.hitl_type.strip().lower() == want]


def search(text: str) -> List[Minion]:
    """Substring search over trigger/subcategory/workflow/notes."""
    q = text.strip().lower()
    return [
        b
        for b in MINIONS
        if q in f"{b.trigger} {b.subcategory} {b.example_rite} {b.notes}".lower()
    ]


def find_minion(minions: List[Minion], minion_id: str) -> Optional[Minion]:
    for b in minions:
        if b.id == minion_id:
            return b
    return None
